];

function markerDefs() {
  var end = draw.marker(10, 10, function (add) {
    add.path('M 0 0 L 10 5 L 0 10 z').fill('#000');
  });
  end.ref(9, 5).orient('auto').markerUnits('strokeWidth');

  var start = draw.marker(10, 10, function (add) {
    add.path('M 10 0 L 0 5 L 10 10 z').fill('#000');
  });
  start.ref(1, 5).orient('auto').markerUnits('strokeWidth');
  return { end: end, start: start };
}

function mathText(parent, s, x, y, size, anchor) {
  var t = parent.text(s)
    .font({ family: 'Times New Roman, Times, serif', size: size || 28, style: 'italic' })
    .fill('#000')
    .attr({
      x: x,
      y: y,
      'text-anchor': anchor || 'middle',
      'dominant-baseline': 'middle',
      'paint-order': 'stroke',
      stroke: '#fff',
      'stroke-width': 4,
      'stroke-linejoin': 'round'
    });
  return t;
}

function plainText(parent, s, x, y, size, anchor) {
  var t = parent.text(s)
    .font({ family: 'Times New Roman, Times, serif', size: size || 26 })
    .fill('#000')
    .attr({
      x: x,
      y: y,
      'text-anchor': anchor || 'middle',
      'dominant-baseline': 'middle',
      'paint-order': 'stroke',
      stroke: '#fff',
      'stroke-width': 4,
      'stroke-linejoin': 'round'
    });
