}

function edge(parent, x1, y1, x2, y2, dashed) {
  var l = parent.line(x1, y1, x2, y2).stroke({ color: '#000', width: 2, linecap: 'round' });
  if (dashed) l.attr('stroke-dasharray', '8,9');
  return l;
}

function highlightBox(parent, x, y, w, h) {
  return parent.rect(w, h).move(x, y).radius(8)
    .fill({ color: '#fff7c2', opacity: 0.35 })
    .stroke({ color: '#c9b34c', width: 1.4, dasharray: '6,5' });
}

function popupify(el, title, body, tip) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip || title, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
}

function drawTopPanels(parent) {
  var boxes = [
    { x: 20, y: 18, w: 145, h: 405 },
    { x: 205, y: 18, w: 205, h: 405 },
    { x: 512, y: 18, w: 420, h: 405 }
  ];
  if (state.stageIndex <= 2) highlightBox(parent, boxes[state.stageIndex].x, boxes[state.stageIndex].y, boxes[state.stageIndex].w, boxes[state.stageIndex].h);

  var a = parent.group();
  mathText(a, 'T(n)', 58, 35, 30);
  plainText(a, '(a)', 58, 430, 28);
  mathText(a, 'T(n) = 2T(n/2) + cn', 190, 96, 24, 'start');
  popupify(a, 'Recurrence', 'The expression T(n)=2T(n/2)+cn says that a problem of size n creates two recursive subproblems of size n/2 and pays cn nonrecursive work at that level.', 'The recurrence to unfold');

  var b = parent.group();
  mathText(b, 'cn', 305, 35, 30);
  edge(b, 292, 65, 254, 170);
  edge(b, 320, 65, 360, 170);
  mathText(b, 'T(n/2)', 238, 195, 28);
  mathText(b, 'T(n/2)', 378, 195, 28);
  plainText(b, '(b)', 305, 430, 28);
  popupify(b, 'One expansion', 'After one substitution, the root has local cost cn and two unresolved calls T(n/2). Each unresolved label can be expanded by the same rule.', 'First recurrence expansion');

  var c = parent.group();
  mathText(c, 'cn', 742, 35, 30);
  edge(c, 720, 65, 605, 170);
  edge(c, 766, 65, 880, 170);
  mathText(c, 'cn/2', 592, 195, 28);
  mathText(c, 'cn/2', 895, 195, 28);
  edge(c, 580, 225, 540, 340);
  edge(c, 612, 225, 650, 340);
  edge(c, 880, 225, 840, 340);
  edge(c, 912, 225, 950, 340);
  mathText(c, 'T(n/4)', 525, 365, 28);
  mathText(c, 'T(n/4)', 672, 365, 28);
  mathText(c, 'T(n/4)', 825, 365, 28);
  mathText(c, 'T(n/4)', 965, 365, 28);
  plainText(c, '(c)', 742, 430, 28);
  popupify(c, 'Two expansions', 'There are now two nodes on the cn/2 level. Their total is 2·cn/2 = cn, previewing why every internal level has the same total cost.', 'Second expansion: two half-cost nodes');
}

function dottedArrow(parent, defs, x1, y1, x2, y2) {
  return parent.line(x1, y1, x2, y2)
    .stroke({ color: '#000', width: 4, linecap: 'butt' })
    .attr({ 'stroke-dasharray': '3,5', 'marker-end': defs.end });
}

function drawDoubleArrow(parent, defs, x, y1, y2) {
  parent.line(x, y1, x, y2)
    .stroke({ color: '#000', width: 1.7 })
    .attr({ 'marker-start': defs.start, 'marker-end': defs.end });
}

function drawBrace(parent, x1, x2, y, depth) {
  var mid = (x1 + x2) / 2;
  return parent.path('M ' + x1 + ' ' + y +
    ' C ' + (x1 + 35) + ' ' + (y + depth) + ' ' + (mid - 85) + ' ' + (y + 5) + ' ' + mid + ' ' + (y + depth) +
    ' C ' + (mid + 85) + ' ' + (y + 5) + ' ' + (x2 - 35) + ' ' + (y + depth) + ' ' + x2 + ' ' + y)
    .fill('none').stroke({ color: '#000', width: 1.4, linecap: 'round' });
}

function drawFullTree(parent, defs) {
  if (state.stageIndex === 3) highlightBox(parent, 90, 575, 810, 760);

  var k = state.k;
  var n = Math.pow(2, k);
  var root = { x: 405, y: 610 };
  var lvl1 = [{ x: 255, y: 775 }, { x: 560, y: 775 }];
  var lvl2 = [{ x: 175, y: 955 }, { x: 335, y: 955 }, { x: 500, y: 955 }, { x: 665, y: 955 }];

  if (state.overlay) {
    parent.rect(560, 36).move(140, root.y - 18).fill({ color: '#ffe88a', opacity: 0.16 }).stroke('none');
    parent.rect(560, 36).move(140, lvl1[0].y - 18).fill({ color: '#ffe88a', opacity: 0.16 }).stroke('none');
    parent.rect(560, 36).move(140, lvl2[0].y - 18).fill({ color: '#ffe88a', opacity: 0.16 }).stroke('none');
    parent.rect(610, 36).move(105, 1198).fill({ color: '#ffe88a', opacity: 0.16 }).stroke('none');
  }

  mathText(parent, 'cn', root.x, root.y, 30);
  edge(parent, 385, 638, lvl1[0].x + 15, lvl1[0].y - 40);
  edge(parent, 430, 638, lvl1[1].x - 15, lvl1[1].y - 40);

  mathText(parent, 'cn/2', lvl1[0].x, lvl1[0].y, 29);
  mathText(parent, 'cn/2', lvl1[1].x, lvl1[1].y, 29);
  edge(parent, lvl1[0].x - 18, lvl1[0].y + 30, lvl2[0].x + 15, lvl2[0].y - 36);
  edge(parent, lvl1[0].x + 18, lvl1[0].y + 30, lvl2[1].x - 15, lvl2[1].y - 36);
  edge(parent, lvl1[1].x - 18, lvl1[1].y + 30, lvl2[2].x + 15, lvl2[2].y - 36);
  edge(parent, lvl1[1].x + 18, lvl1[1].y + 30, lvl2[3].x - 15, lvl2[3].y - 36);

  for (var i = 0; i < lvl2.length; i++) mathText(parent, 'cn/4', lvl2[i].x, lvl2[i].y, 28);

  for (var j = 0; j < lvl2.length; j++) {
    edge(parent, lvl2[j].x - 18, lvl2[j].y + 30, lvl2[j].x - 42, 1080, true);
    edge(parent, lvl2[j].x + 18, lvl2[j].y + 30, lvl2[j].x + 42, 1080, true);
  }

  var leafXs;
  if (k <= 2) {
    leafXs = [175, 335, 500, 665];
  } else if (k === 3) {
    leafXs = [140, 220, 300, 380, 480, 560, 640, 720];
  } else {
    leafXs = [138, 218, 298, 378, 475, 640, 720];
  }

  for (var m = 0; m < leafXs.length; m++) {
    parent.line(leafXs[m], 1135, leafXs[m], 1180).stroke({ color: '#000', width: 1.4, dasharray: '7,7' });
    mathText(parent, 'c', leafXs[m], 1210, 27);
  }
  if (k >= 4) mathText(parent, '...', 555, 1210, 30);

  drawBrace(parent, 105, 745, 1265, 30);
  mathText(parent, 'n = ' + n, 405, 1326, 27);

  drawDoubleArrow(parent, defs, 48, 625, 1210);
  mathText(parent, 'lg n = ' + k, 48, 905, 26);
  for (var tick = 0; tick <= k; tick++) {
    var ty = 645 + (1210 - 645) * (tick / k);
    parent.line(39, ty, 57, ty).stroke({ color: '#000', width: 1 });
  }

  if (state.overlay) {
    var o = parent.group();
    var arrows = [
      { y: root.y, textY: root.y, title: 'Root level total', body: 'At the root there is one node of cost cn, so the level sum is cn.' },
      { y: lvl1[0].y, textY: lvl1[0].y, title: 'First recursive level total', body: 'This level has two nodes, each costing cn/2. The sum is 2·cn/2 = cn.' },
      { y: lvl2[0].y, textY: lvl2[0].y, title: 'Second recursive level total', body: 'This level has four nodes, each costing cn/4. The sum is 4·cn/4 = cn.' },
      { y: 1210, textY: 1210, title: 'Leaf-level total', body: 'There are n leaves of constant cost c, so the leaves contribute cn in total.' }
    ];
    for (var a = 0; a < arrows.length; a++) {
      var ar = dottedArrow(o, defs, a === 0 ? 480 : (a === 1 ? 610 : (a === 2 ? 720 : 770)), arrows[a].y, 820, arrows[a].y);
      mathText(o, 'cn', 875, arrows[a].textY, 28);
      popupify(ar, arrows[a].title, arrows[a].body, 'Level sum = cn');
    }
    mathText(o, '⋮', 875, 1070, 44);
    o.line(805, 1300, 895, 1300).stroke({ color: '#000', width: 1.5 });
  } else {
    parent.line(805, 1300, 895, 1300).stroke({ color: '#000', width: 1.2, opacity: 0.35 });
  }

  mathText(parent, 'Total: cn lg n + cn', 805, 1365, 30, 'middle');
  plainText(parent, '(d)', 405, 1378, 28);

  var rootHit = parent.circle(78).center(root.x, root.y).fill({ color: '#fff', opacity: 0.01 }).stroke('none');
  popupify(rootHit, 'Why every level sums to cn', 'At depth i there are 2^i subproblems, and each has local cost cn/2^i. Multiplying gives 2^i·cn/2^i = cn.', 'Hover/click: level-cost cancellation');
}

function render() {
  draw.clear();
  var defs = markerDefs();
  draw.rect(W, H).fill('#fff');

  drawTopPanels(draw);

  var separator = draw.line(30, 510, 930, 510).stroke({ color: '#eee', width: 1 });
  separator.back();

  drawFullTree(draw, defs);

  document.getElementById('expansionStageVal').value = stageNames[state.stageIndex];
  document.getElementById('problemSizeExponentVal').value = state.k;
  document.getElementById('problemSizeExponentInput').value = state.k;
  document.getElementById('levelCostOverlayInput').checked = state.overlay;
}

function setStageByName(name) {
  var idx = stageNames.indexOf(name);
  if (idx >= 0) state.stageIndex = idx;
}

function trigger_expansionStage() {
  state.stageIndex = (state.stageIndex + 1) % stageNames.length;
  render();
}

function update_problemSizeExponent(v) {
  state.k = Math.max(2, Math.min(8, Math.round(v)));
  render();
}

function toggle_levelCostOverlay(on) {
  state.overlay = !!on;
  render();
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  setStageByName(step.state.expansionStage);
  state.k = step.state.problemSizeExponent;
  state.overlay = !!step.state.levelCostOverlay;
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length;
  render();
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

