function arrowHead(parent, x, y, angle, size, color) {
  var a1 = angle + Math.PI * 0.82;
  var a2 = angle - Math.PI * 0.82;
  var p1x = x + size * Math.cos(a1), p1y = y + size * Math.sin(a1);
  var p2x = x + size * Math.cos(a2), p2y = y + size * Math.sin(a2);
  return parent.polygon(x + ',' + y + ' ' + p1x + ',' + p1y + ' ' + p2x + ',' + p2y)
    .fill(color || '#000').stroke('none');
}

function dottedArrow(parent, x1, y1, x2, y2, active) {
  var color = active ? '#000' : '#000';
  var width = active ? 3.6 : 3.0;
  var g = parent.group();
  g.line(x1, y1, x2 - 18, y2).stroke({ color: color, width: width, linecap: 'butt' }).attr('stroke-dasharray', '3,5');
  arrowHead(g, x2 - 2, y2, 0, 15, color);
  arrowHead(g, x2 - 14, y2, 0, 12, color);
  arrowHead(g, x2 - 26, y2, 0, 9, color);
  return g;
}

function doubleVerticalArrow(parent, x, y1, y2) {
  parent.line(x, y1, x, y2).stroke({ color: '#000', width: 1.5, linecap: 'round' });
  arrowHead(parent, x, y1, -Math.PI / 2, 15, '#000');
  arrowHead(parent, x, y2, Math.PI / 2, 15, '#000');
}

