  return parent.path(
    'M ' + x1 + ' ' + y +
    ' C ' + (x1 + 26) + ' ' + (y + depth * 0.75) + ' ' + (mid - 82) + ' ' + (y + 4) + ' ' + mid + ' ' + (y + depth) +
    ' C ' + (mid + 82) + ' ' + (y + 4) + ' ' + (x2 - 26) + ' ' + (y + depth * 0.75) + ' ' + x2 + ' ' + y
