function drawFullTree(parent) {
  if (state.stageIndex === 3) highlightBox(parent, 96, 555, 642, 744);

  var k = state.k;
  var n = Math.pow(2, k);
  var root = { x: 430, y: 600 };
  var lvl1 = [{ x: 275, y: 775 }, { x: 585, y: 775 }];
  var lvl2 = [{ x: 198, y: 948 }, { x: 352, y: 948 }, { x: 508, y: 948 }, { x: 662, y: 948 }];

  if (state.overlay) {
    parent.rect(500, 32).move(315, root.y - 20).fill({ color: '#fff2a6', opacity: 0.22 }).stroke('none');
    parent.rect(560, 32).move(260, lvl1[0].y - 19).fill({ color: '#fff2a6', opacity: 0.18 }).stroke('none');
    parent.rect(610, 32).move(175, lvl2[0].y - 19).fill({ color: '#fff2a6', opacity: 0.16 }).stroke('none');
    parent.rect(680, 32).move(135, 1210 - 19).fill({ color: '#fff2a6', opacity: 0.16 }).stroke('none');
  }

  mathText(parent, 'cn', root.x, root.y, 30);
  edge(parent, root.x - 20, root.y + 28, lvl1[0].x + 18, lvl1[0].y - 38);
  edge(parent, root.x + 25, root.y + 28, lvl1[1].x - 18, lvl1[1].y - 38);

  mathText(parent, 'cn/2', lvl1[0].x, lvl1[0].y, 28);
  mathText(parent, 'cn/2', lvl1[1].x, lvl1[1].y, 28);
  edge(parent, lvl1[0].x - 16, lvl1[0].y + 27, lvl2[0].x + 14, lvl2[0].y - 36);
  edge(parent, lvl1[0].x + 16, lvl1[0].y + 27, lvl2[1].x - 14, lvl2[1].y - 36);
  edge(parent, lvl1[1].x - 16, lvl1[1].y + 27, lvl2[2].x + 14, lvl2[2].y - 36);
  edge(parent, lvl1[1].x + 16, lvl1[1].y + 27, lvl2[3].x - 14, lvl2[3].y - 36);

  for (var i = 0; i < lvl2.length; i++) {
    mathText(parent, 'cn/4', lvl2[i].x, lvl2[i].y, 27);
    edge(parent, lvl2[i].x - 13, lvl2[i].y + 26, lvl2[i].x - 36, 1083, true);
    edge(parent, lvl2[i].x + 13, lvl2[i].y + 26, lvl2[i].x + 36, 1083, true);
  }

  var leftLeaf = 145, rightLeaf = 712;
  var maxShown = Math.min(12, Math.max(4, n));
  var leafXs = [];
  for (var j = 0; j < maxShown; j++) {
    leafXs.push(leftLeaf + (rightLeaf - leftLeaf) * (j / (maxShown - 1)));
  }

  for (var m = 0; m < leafXs.length; m++) {
    var x = leafXs[m];
    if (m === Math.floor(maxShown / 2) && maxShown > 7) continue;
    parent.line(x, 1138, x, 1184).stroke({ color: '#000', width: 1.4, dasharray: '7,7' });
    mathText(parent, 'c', x, 1215, 26);
  }
  if (maxShown > 7) mathText(parent, '...', (leftLeaf + rightLeaf) / 2, 1215, 30);

  drawBrace(parent, 110, 735, 1262, 28);
  mathText(parent, 'n', 425, 1320, 30);
  if (k !== 4) mathText(parent, '= ' + n, 456, 1320, 22, 'start');

  doubleVerticalArrow(parent, 48, 610, 1210);
  mathText(parent, 'lg n', 48, 905, 28);
  for (var tick = 0; tick <= k; tick++) {
    var ty = 630 + (1210 - 630) * (tick / Math.max(1, k));
    parent.line(39, ty, 57, ty).stroke({ color: '#000', width: 1 });
  }

  var arrowRows = [
    { x1: 510, y: root.y, tx: 870, title: 'Root level total', body: 'At depth 0 there is one node, and its cost is cn, so the level total is cn.' },
    { x1: 635, y: lvl1[0].y, tx: 870, title: 'First recursive level total', body: 'There are two nodes of cost cn/2, so the level total is 2·cn/2 = cn.' },
    { x1: 735, y: lvl2[0].y, tx: 870, title: 'Second recursive level total', body: 'There are four nodes of cost cn/4, so the level total is 4·cn/4 = cn.' },
    { x1: 760, y: 1215, tx: 870, title: 'Leaf total', body: 'There are n leaves, each costing c, so the leaf level contributes cn.' }
  ];

  for (var a = 0; a < arrowRows.length; a++) {
    var row = arrowRows[a];
    var arr = dottedArrow(parent, row.x1, row.y, 835, row.y, state.overlay);
    mathText(parent, 'cn', row.tx, row.y, 28);
    popupify(arr, row.title, row.body, 'Level total = cn');
  }
  mathText(parent, '⋮', 872, 1088, 44);
  parent.line(805, 1294, 900, 1294).stroke({ color: '#000', width: 1.4 });

  mathText(parent, 'Total: cn lg n + cn', 805, 1375, 30, 'middle');
  plainText(parent, '(d)', 425, 1375, 28);

  var rootHit = parent.circle(82).center(root.x, root.y).fill({ color: '#fff', opacity: 0.01 }).stroke('none');
  popupify(rootHit, 'Why each level sums to cn', 'At depth i there are 2^i subproblems. Each has local cost cn/2^i, so multiplying gives 2^i·cn/2^i = cn.', 'Click for the cancellation 2^i · cn/2^i');
}

function render() {
  draw.clear();
  draw.rect(W, H).fill('#fff');
  drawTopPanels(draw);
  drawFullTree(draw);

  document.getElementById('expansionStageVal').value = stageNames[state.stageIndex];
  document.getElementById('problemSizeExponentVal').value = state.k;
