  ];

  for (var a = 0; a < arrowRows.length; a++) {
    var row = arrowRows[a];
    var arr = dottedArrow(parent, row.x1, row.y, 835, state.overlay);
    mathText(parent, 'cn', 880, row.y, 28);
    popupify(arr, row.title, row.body, 'Level total = cn');
  }

  mathText(parent, '⋮', 880, 1088, 44);
  parent.line(815, 1294, 905, 1294).stroke({ color: '#000', width: 1.4 });
  plainText(parent, 'Total: cn lg n + cn', 790, 1375, 30, 'middle');
  plainText(parent, '(d)', 425, 1375, 28);

  var rootHit = parent.circle(86).center(root.x, root.y).fill({ color: '#fff', opacity: 0.01 }).stroke('none');
  popupify(rootHit, 'Why every internal level sums to cn', 'At depth i there are 2^i subproblems. Each one costs cn/2^i, so 2^i · cn/2^i = cn. The height is lg n, giving cn lg n internal work plus cn leaf work.', 'Click for the cancellation 2^i · cn/2^i');
}

function render() {
  draw.clear();
  draw.rect(W, H).fill('#fff');
  drawTopPanels(draw);
  drawFullTree(draw);

  document.getElementById('expansionStageVal').value = stageNames[state.stageIndex];
  document.getElementById('problemSizeExponentVal').value = state.k;
  document.getElementById('problemSizeExponentInput').value = state.k;
  document.getElementById('levelCostOverlayInput').checked = state.overlay;
}

function setStageByName(name) {
  var idx = stageNames.indexOf(name);
  if (idx >= 0) state.stageIndex = idx;
}

function trigger_expansionStage() {
  state.stageIndex = (state.stageIndex + 1) % stageNames.length;
  state.focus = true;
  render();
  showPopup(
    'Expanding the recurrence',
    'Each button press focuses the next expansion: T(n), then cn with two T(n/2) children, then the next split, and finally the full recursion tree. The recurrence being expanded is T(n)=2T(n/2)+cn.'
  );
}

function update_problemSizeExponent(v) {
  state.k = Math.max(2, Math.min(8, Math.round(v)));
  state.focus = true;
  state.stageIndex = 3;
  render();
}

function toggle_levelCostOverlay(on) {
  state.overlay = !!on;
  state.focus = true;
  render();
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  setStageByName(step.state.expansionStage);
  state.k = step.state.problemSizeExponent;
  state.overlay = !!step.state.levelCostOverlay;
  state.focus = currentStep > 0;
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length;
  render();
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
